using System;
using System.IO;
using System.Linq;
using System.Collections;
using UnityEngine;
using CatCafePreview.Standalone;
namespace CatCafePreview {
 public sealed class StandaloneReadSkipSmoke:MonoBehaviour {
  string output;int checks;
  void Check(bool value,string label){checks++;if(!value)throw new Exception(label);}
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--catcafe-read-check");if(i<0)return;var q=new GameObject("Read skip QA").AddComponent<StandaloneReadSkipSmoke>();DontDestroyOnLoad(q);q.output=Path.GetFullPath(a[i+1]);Directory.CreateDirectory(q.output);Application.runInBackground=true;q.StartCoroutine(q.Guard());}
  IEnumerator Guard(){var run=Run();while(true){object value;try{if(!run.MoveNext())yield break;value=run.Current;}catch(Exception e){File.WriteAllText(Path.Combine(output,"failure.txt"),e.ToString());Application.Quit(1);yield break;}yield return value;}}
  IEnumerator Run(){yield return new WaitForSecondsRealtime(1);var rules=StandaloneSupportConversationSmoke.Rules();var b=new LocalCafeBackend(Path.Combine(output,"profile"),rules);for(int seed=0;seed<100000;seed++){var sim=new CafeSimulation(rules,seed,"free");if(sim.CurrentStoreEvent.type=="support"){b.Simulation.Restore(sim.State);break;}}b.PrepareEquipmentConversation();bool restart=Environment.GetCommandLineArgs().Contains("--read-resume");if(restart)StandaloneDispatchIntroductionConversationSmoke.Good(b,"load_game",slot:9);CafeBackends.UseLocal(b);UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);var c=FindObjectOfType<PythonStateClient>();Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(c,new object[]{b.View()});apply();yield return null;var ui=c.GetComponent<EquipmentConversationPanel>();var p=b.EquipmentConversation.progress;CafeOptions.Current.instant=true;ui.Refresh();
   if(restart){Check(p.branch_id!="introduction" && p.node==1,"result save restart lost");var intro=CafeEquipmentDialogue.Lines(b.EquipmentConversation,"introduction");Check(b.ReadHistory.Contains(CafeReadStore.Key(p.conversation_id,"introduction",intro,0),0,intro[0].text.Length),"restart lost independent read");string original=JsonUtility.ToJson(b.Simulation.State);ui.SkipRead();Check(p.node==1 && original==JsonUtility.ToJson(b.Simulation.State),"restart result skipped/repaid");File.WriteAllText(Path.Combine(output,"restart.txt"),"PASS "+checks);Application.Quit(0);yield break;}
   string facts=JsonUtility.ToJson(b.Simulation.State);ui.SkipRead();Check(p.node==0,"unread skipped");yield return null;
   for(int n=0;n<20 && p.node<2;n++){ui.Next();yield return null;}
   Check(p.node==2,"normal read did not reach important section");p.node=0;p.page_offset=0;ui.Refresh();yield return null;ui.SkipRead();ui.SkipRead();Check(p.node==2,"read skip failed or repeat crossed protected section");Check(JsonUtility.ToJson(b.Simulation.State)==facts,"skip changed gameplay");Check(!p.completed && b.Replays.Load().entries.Length==0,"skip unlocked Extra");
   ui.SkipRead();yield return null;Check(p.node==2,"important skipped");
   foreach(var size in new[]{new Vector2Int(1280,800),new Vector2Int(1024,768)}){Screen.SetResolution(size.x,size.y,false);yield return new WaitForSecondsRealtime(1);p.node=0;p.page_offset=0;ui.Refresh();yield return null;var button=ui.GetComponentsInChildren<UnityEngine.UI.Button>().First(x=>x.name=="既読部分をスキップ");Check(button.interactable,"read button disabled");ScreenCapture.CaptureScreenshot(Path.Combine(output,size.x+"x"+size.y+".png"));yield return new WaitForSecondsRealtime(.4f);button.onClick.Invoke();yield return null;Check(p.node==2,"resolution skip crossed important");}
   ui.Close();ui.Open();yield return null;Check(p.node==2,"close lost position");p.node=3;ui.Refresh();yield return null;ui.SkipRead();Check(p.node==3 && b.Simulation.StoreEventWaiting,"choice answered");
   yield return null;ui.Answer(false);yield return null;Check(b.Simulation.StoreEventWaiting,"answer executed without final confirmation");var confirm=ui.GetComponentsInChildren<UnityEngine.UI.Button>().First(x=>x.name=="この内容で回答");ui.SkipRead();Check(b.Simulation.StoreEventWaiting,"skip confirmed payment");yield return null;confirm.onClick.Invoke();yield return new WaitForSecondsRealtime(.5f);apply();yield return null;p=b.EquipmentConversation.progress;Check(p.branch_id=="small","support answer missing");p.node=1;p.page_offset=0;ui.Refresh();yield return null;facts=JsonUtility.ToJson(b.Simulation.State);ui.SkipRead();Check(p.node==1 && facts==JsonUtility.ToJson(b.Simulation.State),"result skipped or paid twice");StandaloneDispatchIntroductionConversationSmoke.Good(b,"save_game",slot:9);
   int completions=0;for(int n=0;n<30 && ui.Showing;n++){bool before=p.completed;ui.Next();if(!before && p.completed)completions++;yield return null;}Check(completions==1 && p.completed,"completion repeated or absent");Check(b.Replays.Load().entries.Length==1,"result Extra absent");string readBefore=File.ReadAllText(Path.Combine(output,"profile/conversation-read-v1.json"));facts=JsonUtility.ToJson(b.Simulation.State);UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafeTitle");yield return new WaitForSecondsRealtime(1);var extra=FindObjectOfType<PythonTitleScreen>().GetComponent<TitleExtraPanel>();extra.Open();extra.OpenReplay(CafeEquipmentDialogue.SupportId+"/small");yield return null;extra.Replay.SkipRead();extra.Replay.Next();yield return null;extra.Replay.Close();Check(facts==JsonUtility.ToJson(b.Simulation.State) && readBefore==File.ReadAllText(Path.Combine(output,"profile/conversation-read-v1.json")),"Extra changed gameplay/read profile");
   int tripChecks=StandaloneRoundTripConversationSmoke.BackendChecks(Path.Combine(output,"trips"),false);Check(tripChecks>0,"trip regression absent");int equipmentChecks=StandaloneEquipmentConversationSmoke.Run(Path.Combine(output,"equipment"));int supportChecks=StandaloneSupportConversationSmoke.Run(Path.Combine(output,"support"));
   UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(1);c=FindObjectOfType<PythonStateClient>();var tripRules=StandaloneEncounterConversationSmoke.Rules();tripRules.dispatch_unlocks=tripRules.dispatch_unlocks.Where(x=>x.id!="mountain_lodge_visit").ToArray();tripRules.dispatch_trouble.base_probability=tripRules.dispatch_trouble.stress_probability=0;var trip=new LocalCafeBackend(Path.Combine(output,"trips/shopping_street_event1/accept"),tripRules);CafeBackends.UseLocal(trip);
   foreach(int slot in new[]{1,5,6}){StandaloneDispatchIntroductionConversationSmoke.Good(trip,"load_game",slot:slot);typeof(PythonStateClient).GetMethod("Accept",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(c,new object[]{trip.View()});yield return null;var adv=c.GetComponent<DispatchConversationPanel>();adv.Open();yield return null;var row=trip.DispatchConversation;var q=row.Current;var lines=CafeDispatchDialogue.Lines(row.stage,q.branch_id,trip.Simulation.Definition(row.cat_id).name,row.Destination,trip.Simulation.State.dispatches.FirstOrDefault());for(int i=0;i<lines.Length;i++)trip.ReadHistory.Remember(CafeReadStore.Key(q.conversation_id,q.branch_id,lines,i),0,lines[i].text.Length);q.node=slot==5?1:0;q.page_offset=0;adv.Refresh();yield return null;facts=JsonUtility.ToJson(trip.Simulation.State);adv.SkipRead();Check(q.node==(slot==6?0:2),"dispatch stop incorrect slot "+slot);Check(facts==JsonUtility.ToJson(trip.Simulation.State) && !q.completed,"dispatch skip executed action");adv.Close();yield return null;}
   File.WriteAllText(Path.Combine(output,"regressions.txt"),"trip="+tripChecks+" equipment="+equipmentChecks+" support="+supportChecks);
   File.WriteAllText(Path.Combine(output,"result.txt"),"PASS "+checks+"; support introduction: 2 normal next operations -> 1 skip; condition, choice, confirmation and result retained");Application.Quit(0);
  }
 }
}
